const response = pm.response.json();
const currency = pm.collectionVariables.get("currentCurrency");

pm.test("Response status is 200", () => {
    pm.response.to.have.status(200);
});

pm.test("Response time is below 3 seconds", () => {
    pm.expect(pm.response.responseTime).to.be.below(3000);
});

if (currency === "INVALID") {
    pm.test("Invalid currency returns an error", () => {
        pm.expect(response.result).to.eql("error");
    });
} else {
    pm.test("Valid currency returns exchange rates", () => {
        pm.expect(response.result).to.eql("success");
        pm.expect(response.base_code).to.eql(currency);
        pm.expect(response.rates).to.be.an("object");
    });
}

const currencies = JSON.parse(pm.collectionVariables.get("testData"));
const index = Number(pm.collectionVariables.get("testIndex"));

if (index < currencies.length - 1) {
    pm.collectionVariables.set("testIndex", String(index + 1));
    pm.execution.setNextRequest("Get Latest Exchange Rates");
} else {
    pm.collectionVariables.unset("testIndex");
    pm.execution.setNextRequest(null);
}

const currencies = ["EUR",  "USD", "USA"];

let index = parseInt(pm.collectionVariables.get("testIndex"), 10);

if (isNaN(index) || index < 0 || index >= currencies.length) {
    index = 0;
}

pm.collectionVariables.set("testIndex", String(index));
pm.collectionVariables.set("currentCurrency", currencies[index]);

console.log("Currency:", currencies[index]);
console.log("Index:", index);
